class Solution { int swaps(const string& s,char start){int mismatch=0;for(int i=0;i<(int)s.size();++i){char expected=i%2?(start=='0'?'1':'0'):start;mismatch+=s[i]!=expected;}return mismatch/2;}public: int minSwaps(string s){int zeros=count(s.begin(),s.end(),'0'),ones=s.size()-zeros;if(abs(zeros-ones)>1)return -1;if(zeros==ones)return min(swaps(s,'0'),swaps(s,'1'));return swaps(s,zeros>ones?'0':'1');} };
